1	import React, { useEffect, useState } from 'react';
2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
3	import { ZimmLogo } from 'app/components/ui-kits/atoms/zimmLogo';
4	import { ZimmSubscribeSection } from 'app/components/ui-kits/organisms/zimmSubscribeSection';
5	import { noop } from '@salesforce/retail-react-app/app/utils/utils';
6	import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
7	import { useHistory } from 'react-router-dom';
8	import { HOME_HREF } from '@salesforce/retail-react-app/app/constants';
9	import type { ContentfulClientApi } from 'contentful';
10	import { useContentfulClient } from 'app/hooks/useContentfulClient';
11	import { useUiCopy } from 'app/hooks/useUiCopy';
12	import { CONTENTFUL_FALLBACK_LOCALE } from 'app/config/contentful';
13	import { filterByRegion, pickMostSpecificByRegion } from 'app/utils/resolveByRegion';
14	import type { FooterConfigEntry, NavGroupEntry, LinkEntry } from 'app/types/contentful';
15	import { FooterNavColumn } from './footerNavColumn';
16	import { BottomBar } from './bottomBar';
17	
18	const ZIMM_FOOTER_RECIPE = 'ZimmFooter';
19	
20	// Contentful resolves nested references `include` levels deep, and the footer model is exactly
21	// three: footerConfig → navGroups (1) → links (2) → regions (3). Depth 3 is the minimum that
22	// populates `entry.fields.regions[].fields.siteId`, which isEligible reads.
23	//
24	// Getting this wrong fails hard, not gracefully. At 2, a region-scoped link's `regions` array
25	// arrives as unresolved link stubs with no `fields` (the SDK keeps unresolvable links by default
26	// — `withoutUnresolvableLinks` is not passed), so `region.fields.siteId` throws, the `.catch`
27	// below swallows it, footerData stays null and the *entire* footer renders nothing — columns,
28	// logo band and bottom bar included. Not a house default either: useContentful.ts hardcodes 2
29	// for asset resolution, per its own comments, which is a different concern.
30	const FOOTER_INCLUDE_DEPTH = 3;
31	
32	// ---------------------------------------------------------------------------
33	// Types
34	// ---------------------------------------------------------------------------
35	type FooterProps = {
36	  /** Contentful FooterConfigEntry. Pass FOOTER_FIXTURE from index.stories.content.ts in stories/tests. */
37	  data: FooterConfigEntry;
38	  copyrightYear?: number;
39	  /** Forces SubscribeSection into its post-submit state. For Storybook/tests only. */
40	  initialSubscribed?: boolean;
41	  /**
42	   * Opt in to the HPC-035 first/last-name capture modal. Defaults to false: SFCC-55 ships the
43	   * Stay in Touch section as an input plus submit button only, and the modal has no design yet.
44	   */
45	  enableNameCapture?: boolean;
46	  /** Click handler for the wordmark. Mirrors the header's onLogoClick prop, defaulting to
47	   *  noop so the presentational Footer never navigates on its own. */
48	  onLogoClick?: () => void;
49	  /** href for the Privacy Policy link inside the subscribe modal (HPC-037). Locale-aware at runtime. */
50	  privacyPolicyHref?: string;
51	};
52	
53	// ---------------------------------------------------------------------------
54	// Footer
55	// ---------------------------------------------------------------------------
56	
57	/**
58	 * Zimmermann global footer — presentational. Receives its content as props and fetches
59	 * nothing, matching every other Contentful-backed component in the repo (`DuplexSection`,
60	 * `HeroBanner`, `ProductHero`, `VideoEmbed`).
61	 *
62	 * Composed from independently-exported organisms/molecules (ui-kits/organisms/
63	 * zimmSubscribeSection, ui-kits/molecules/zimmContactIconRow via FooterNavColumn) rather than
64	 * defining them inline — see .claude/rules/overrideStyling.md for the reasoning. This file owns
65	 * only the footer's own shell layout: content row, nav-column wrapper, logo band, bottom bar.
66	 *
67	 * `data` is required by design: static content belongs in the story or in the container below,
68	 * never baked into the component that renders production UI. Omneo email submit and Cookie
69	 * Settings are separate stories (HPC-035, HPC-038).
70	 */
71	export const Footer = ({
72	  data,
73	  copyrightYear = new Date().getFullYear(),
74	  initialSubscribed = false,
75	  privacyPolicyHref = '#',
76	  onLogoClick = noop,
77	  enableNameCapture = false,
78	}: FooterProps) => {
79	  const {
80	    subscribeHeading,
81	    subscribeBody,
82	    navGroups,
83	    legalLinks = [],
84	    copyrightOwner,
85	    phoneHref,
86	    phoneLabel,
87	    whatsAppHref,
88	    whatsAppLabel,
89	    emailHref,
90	    emailLabel,
91	  } = data.fields;
92	
93	  const legalItems = legalLinks.map((e) => ({ label: e.fields.label, href: e.fields.href }));
94	  const styles = useMultiStyleConfig(ZIMM_FOOTER_RECIPE, {});
95	  const { t } = useUiCopy();
96	
97	  return (
98	    <chakra.footer role="contentinfo" __css={styles.container}>
99	      <chakra.div __css={styles.main}>
100	        <chakra.div __css={styles.contentRow}>
101	          <chakra.div __css={styles.subscribe}>
102	            <ZimmSubscribeSection
103	              heading={subscribeHeading ?? ''}
104	              body={subscribeBody ?? ''}
105	              initialSubscribed={initialSubscribed}
106	              privacyPolicyHref={privacyPolicyHref}
107	              enableNameCapture={enableNameCapture}
108	            />
109	          </chakra.div>
110	
111	          <chakra.div __css={styles.links}>
112	            <chakra.div __css={styles.linksInner}>
113	              {navGroups.map((group) => (
114	                <FooterNavColumn
115	                  key={group.sys.id}
116	                  group={group}
117	                  phoneHref={phoneHref}
118	                  phoneLabel={phoneLabel}
119	                  whatsAppHref={whatsAppHref}
120	                  whatsAppLabel={whatsAppLabel}
121	                  emailHref={emailHref}
122	                  emailLabel={emailLabel}
123	                />
124	              ))}
125	            </chakra.div>
126	          </chakra.div>
127	        </chakra.div>
128	
129	        <chakra.div __css={styles.logo}>
130	          {/* Button + programmatic nav, matching the header's wordmark rather than an <a href>.
131	              The handler comes from FooterContainer — see the note there on why it uses
132	              buildUrl + history.push rather than useNavigation. styles.logoButton is a chrome
133	              reset only, so the logo keeps its own geometry. */}
134	          <chakra.button
135	            type="button"
136	            aria-label={t('footer.button.assistive_msg.logo', 'Zimmermann home')}
137	            onClick={onLogoClick}
138	            __css={styles.logoButton}
139	          >
140	            <ZimmLogo variant="inverse" />
141	          </chakra.button>
142	        </chakra.div>
143	      </chakra.div>
144	
145	      <BottomBar copyrightYear={copyrightYear} copyrightOwner={copyrightOwner ?? ''} legalLinks={legalItems} />
146	    </chakra.footer>
147	  );
148	};
149	
150	// ---------------------------------------------------------------------------
151	// Container — the default export
152	// ---------------------------------------------------------------------------
153	
154	/**
155	 * Contentful's `include`-resolved response nests navGroups/links/regions but applies no
156	 * region scoping of its own — narrow each region-aware array down to the current
157	 * storefront via the shared resolveByRegion utilities.
158	 */
159	export const scopeToRegion = (config: FooterConfigEntry, siteId: string): FooterConfigEntry => {
160	  const navGroups: NavGroupEntry[] = config.fields.navGroups.map(
161	    (group): NavGroupEntry => ({
162	      ...group,
163	      fields: { ...group.fields, links: filterByRegion<LinkEntry>(group.fields.links, siteId) },
164	    }),
165	  );
166	  const legalLinks: LinkEntry[] | undefined = config.fields.legalLinks
167	    ? filterByRegion<LinkEntry>(config.fields.legalLinks, siteId)
168	    : undefined;
169	
170	  return { ...config, fields: { ...config.fields, navGroups, legalLinks } };
171	};
172	
173	/**
174	 * The component SFCC actually renders. Base `_app/index.jsx` resolves
175	 * `@salesforce/retail-react-app/app/components/footer` through the overrides system and renders
176	 * `<Footer />` with **no props**, so there is no upstream container to own the data. This
177	 * wrapper is that seam, and the only place the Contentful fetch lives.
178	 *
179	 * HPC-034: fetches `footerConfig` entries via the Delivery API, then picks the entry scoped
180	 * to the current storefront's region (falls back to the global/unscoped entry once one
181	 * exists). Renders nothing while loading, on fetch failure, or when no entry resolves for
182	 * this region — no fallback to placeholder content once wired to live data, so a Contentful
183	 * outage doesn't silently ship stale placeholder copy to real shoppers. Note this puts a
184	 * fetch inside `components/`, which components.md reserves for containers; if that matters,
185	 * this should move into an `_app` override instead (Tier 2 shared shell — coordinate first).
186	 */
187	const FooterContainer = (props: Omit<FooterProps, 'data'>) => {
188	  // buildUrl + history.push, not useNavigation. useNavigation special-cases the home path
189	  // (`path === '/' ? '/' : updatedHref`), so navigate('/') pushes a bare '/' and skips the
190	  // site/locale prefix — on a prefixed storefront that drops the shopper onto the default
191	  // site. This is the exact pair base _app's onLogoClick uses, so both wordmarks resolve home
192	  // the same way on every storefront.
193	  //
194	  // useMultiSite ships untyped from the base SFCC package. site.id here is the resolved
195	  // SFCC site ID — confirmed against useCountryConfig.ts's identical client-side pattern
196	  // (`c.sfccSiteId === site?.id`), the existing precedent for this exact lookup.
197	  const {
198	    site,
199	    locale: siteLocale,
200	    buildUrl,
201	  } = useMultiSite() as {
202	    site: { id: string };
203	    locale?: { id: string };
204	    buildUrl: (path: string, siteRef?: string, localeRef?: string) => string;
205	  };
206	  const locale = siteLocale?.id ?? CONTENTFUL_FALLBACK_LOCALE;
207	  const history = useHistory();
208	  const { client } = useContentfulClient();
209	  const [footerData, setFooterData] = useState<FooterConfigEntry | null>(null);
210	
211	  useEffect(() => {
212	    if (!client) return;
213	    let cancelled = false;
214	
215	    // useContentfulClient types the client as ContentfulClientApi<any> for the Experiences
216	    // SDK's benefit — with `any` chain modifiers, EntriesQueries's `locale` field resolves out
217	    // of the type entirely (see useHeaderNav.ts's identical cast for the full explanation).
218	    (client as ContentfulClientApi<undefined>)
219	      .getEntries({ content_type: 'footerConfig', include: FOOTER_INCLUDE_DEPTH, locale })
220	      .then((response) => {
221	        if (cancelled) return;
222	        // The contentful SDK client is loosely typed (see useContentfulClient.ts) —
223	        // FooterConfigEntry mirrors the exact nested-resolved shape `include: 3` produces
224	        // for this content model.
225	        const configs = response.items as unknown as FooterConfigEntry[];
226	        const resolved = pickMostSpecificByRegion<FooterConfigEntry>(configs, site.id);
227	        setFooterData(resolved ? scopeToRegion(resolved, site.id) : null);
