// Storybook reuses one preview iframe across story navigations within a session (no full page
// reload per story), so overriding `navigator.languages`/the cookie without restoring them would
// leak into whichever *other* story renders next, if that story happens to read either — capture
// the true original once per mount (via useState's lazy initializer, so a later re-render can't
// recapture an already-overridden value) and restore both on unmount. The restore itself must be
// the effect's *cleanup*, not its body — the body would just reapply the override, and per the
// comment above, this file's whole seeding technique already depends on that override happening
// synchronously during render, not inside an effect.
const useRestoreBrowserLanguagesOnUnmount = (): ((languages: readonly string[]) => void) => {
  const [originalLanguages] = useState(() => window.navigator.languages);
  useEffect(() => {
    return () => {
      setBrowserLanguages(originalLanguages);
      clearRegionPrefCookie();
    };
  }, [originalLanguages]);
  return setBrowserLanguages;
};

const EligibleExample = () => {
  const setLanguages = useRestoreBrowserLanguagesOnUnmount();
  clearRegionPrefCookie();
  setLanguages(['fr-FR']);
  return <ZimmLanguagePrompt site={SITE} locale={LOCALE} buildUrl={BUILD_URL} />;
};

/** A shopper on `/it-eu/` (Italian storefront) whose browser reports French — matches the build
 *  plan's own worked example. Nothing suppresses the prompt, so it opens on mount. */
export const Eligible: Story = {
  render: () => <EligibleExample />,
};

const SuppressedExample = () => {
  const setLanguages = useRestoreBrowserLanguagesOnUnmount();
  setRegionPrefCookie({ languageSuppressedAt: Math.floor(Date.now() / 1000) });
  setLanguages(['fr-FR']);
  return <ZimmLanguagePrompt site={SITE} locale={LOCALE} buildUrl={BUILD_URL} />;
};

