#!/usr/bin/env node
// Read-only verification script. Queries only (client.entry.getMany) — never creates, publishes,
// updates, or deletes anything. Checks whether the 9 uiCopy entries the 3 seed scripts were meant
// to create are actually live in the target Contentful environment, before those scripts are
// deleted from the repo.

import { createClient, resolveTarget, checkEnv } from '/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/scripts/contentful/setup/_shared.mjs';

checkEnv(['CONTENTFUL_MANAGEMENT_TOKEN', 'CONTENTFUL_SPACE_ID']);
const target = resolveTarget(['--target', 'dev']);

const EXPECTED = {
  'regional.locationPrompt.heading': "Looks like you're {inCountry}",
  'regional.locationPrompt.body':
    "You're currently shopping on {currentStore}. Switch to {targetStore} for local pricing, currency and shipping options.",
  'regional.locationPrompt.cta.switch': 'Switch to {targetStore}',
  'regional.locationPrompt.cta.stay': 'Stay on {currentStore}',
  'regional.languagePrompt.heading': 'Welcome to Zimmermann Europe',
  'regional.languagePrompt.body':
    "Welcome to Zimmermann Europe. We noticed you're {inCountry}, would you like to view our site {inLanguage}?",
  'regional.languagePrompt.cta.switch': 'View {inLanguage}',
  'regional.languagePrompt.cta.stay': 'Continue {inCurrentLanguage}',
  'drawer.close': 'Close',
};

const client = createClient();

const existing = [];
let skip = 0;
let total = Infinity;
while (existing.length < total) {
  const page = await client.entry.getMany({
    environmentId: target,
    query: { content_type: 'uiCopy', limit: 1000, skip },
  });
  total = page.total;
  existing.push(...page.items);
  skip += page.items.length;
  if (page.items.length === 0) break;
}

const byKey = new Map(existing.map((e) => [e.fields?.key?.['en'], e]));

console.log(`\nTarget environment: ${target}`);
console.log(`Total uiCopy entries found in space: ${existing.length}\n`);

let allGood = true;
for (const [key, expectedValue] of Object.entries(EXPECTED)) {
  const entry = byKey.get(key);
  if (!entry) {
    console.log(`❌ MISSING  ${key}`);
    allGood = false;
    continue;
  }
  const published = entry.sys.publishedVersion != null;
  const actualValue = entry.fields?.value?.['en'];
  const valueMatches = actualValue === expectedValue;
  const status = published && valueMatches ? '✅' : '⚠️ ';
  console.log(
    `${status} ${key} — published: ${published}, value matches expected: ${valueMatches}` +
      (valueMatches ? '' : `\n     expected: "${expectedValue}"\n     found:    "${actualValue}"`),
  );
  if (!published || !valueMatches) allGood = false;
}

console.log(allGood ? '\nAll 9 entries live, published, and matching.' : '\nAt least one entry is missing, unpublished, or mismatched — see above.');

