1	import React from 'react';
2	import { describe, test, expect, vi, beforeEach, afterEach } from 'vitest';
3	import { render, screen } from '@testing-library/react';
4	import { ChakraProvider } from '@chakra-ui/react';
5	import theme from 'app/theme';
6	import { ZimmDrawer, CLOSE_LABEL_FALLBACK } from './index';
7	import { useUiCopy } from 'app/hooks/useUiCopy';
8	import { ENTRIES } from '~/scripts/contentful/seedDrawerCloseUiCopy.mjs';
9	
10	// First index.test.tsx for this component (SFCC-831) — zimmDrawer.css.test.ts already covers the
11	// recipe; this file is scoped to the `boxedHeader` capability being introduced here, plus the
12	// minimum regression coverage needed to prove the two pre-existing header paths (`title` and
13	// `labelledBy` alone) still behave exactly as before. It is deliberately not a comprehensive suite
14	// for every existing prop (sizes, titleStyle, finalFocusRef/initialFocusRef, etc.).
15	
16	// ZimmIcon throws under Vitest (base SFCC icons barrel side-effect issue — see testing.md's
17	// "Known gap: ZimmIcon throws under Vitest"). ZimmButton's icon variant, rendered for every one of
18	// ZimmDrawer's own close buttons, imports it at module scope, so every test below needs this
19	// mocked regardless of scenario.
20	vi.mock('app/components/ui-kits/atoms/zimmIcon', () => ({ ZimmIcon: () => null }));
21	
22	// Same technique zimmCountryLanguageMismatch/index.test.tsx uses for the same hook — isolates this
23	// suite from UiCopyProvider's own fetch/lookup logic (covered by its own test coverage) and gives
24	// the close button a fixed, assertable accessible name. Not load-bearing for correctness here —
25	// useUiCopy degrades to the literal fallback ('Close') with no Provider mounted at all (see
26	// useUiCopy.ts) — but kept for consistency with the established pattern elsewhere in this codebase.
27	vi.mock('app/hooks/useUiCopy', () => ({ useUiCopy: vi.fn() }));
28	
29	const mockUseUiCopy = vi.mocked(useUiCopy);
30	const mockT = vi.fn((_key: string, fallback: string) => fallback);
31	
32	const renderDrawer = (ui: React.ReactElement) => render(<ChakraProvider theme={theme}>{ui}</ChakraProvider>);
33	
34	describe('ZimmDrawer', () => {
35	  beforeEach(() => {
36	    mockT.mockImplementation((_key: string, fallback: string) => fallback);
37	    mockUseUiCopy.mockReturnValue({ t: mockT, isLoading: false });
38	  });
39	
40	  afterEach(() => {
41	    vi.clearAllMocks();
42	  });
43	
44	  describe('title (regression check — pre-existing path)', () => {
45	    test('renders the in-flow header box; the dialog is named from the title text', () => {
46	      renderDrawer(
47	        <ZimmDrawer isOpen onClose={vi.fn()} size="large" title="SIGN IN">
48	          <p>Body content</p>
49	        </ZimmDrawer>,
50	      );
51	
52	      const dialog = screen.getByRole('dialog', { name: 'SIGN IN' });
53	      expect(dialog).toBeInTheDocument();
54	
55	      const closeButton = screen.getByRole('button', { name: 'Close' });
56	      expect(closeButton).toBeInTheDocument();
57	
58	      // Same structural landmark used for the new boxedHeader case below: a title <span> then the
59	      // close button's own row, sharing one in-flow header box — not the close button alone. One
60	      // level deeper than before the SFCC-831/689 rework: the boxed close button is now wrapped
61	      // in its own `headerCloseButton` part (a real 44px row — see zimmDrawer.css.ts), so this
62	      // walks through that wrapper to reach the shared header box.
63	      const headerBox = closeButton.parentElement?.parentElement;
64	      expect(headerBox?.children).toHaveLength(2);
65	      expect(headerBox?.children[0].tagName).toBe('SPAN');
66	      expect(headerBox?.children[0]).toHaveTextContent('SIGN IN');
67	      // The header part carries no `position` override in zimmDrawer.css.ts (in-flow) — unlike
68	      // the floating closeButton part asserted in the next describe block.
69	      expect(headerBox).not.toHaveStyle({ position: 'absolute' });
70	    });
71	  });
72	
73	  describe('labelledBy, no boxedHeader (regression check — pre-existing path)', () => {
74	    test('close button floats (not boxed); the dialog is named from the external labelledBy target, not any rendered header text', () => {
75	      renderDrawer(
76	        <div>
77	          <h2 id="ext-label">External heading</h2>
78	          <ZimmDrawer isOpen onClose={vi.fn()} size="small" labelledBy="ext-label">
79	            <p>Body content</p>
80	          </ZimmDrawer>
81	        </div>,
82	      );
83	
84	      const dialog = screen.getByRole('dialog', { name: 'External heading' });
85	      expect(dialog).toBeInTheDocument();
86	
87	      const closeButton = screen.getByRole('button', { name: 'Close' });
88	      expect(closeButton).toBeInTheDocument();
89	
90	      // No title-row sibling: the floating close button's own box has exactly one child (the
91	      // button itself) — the boxed treatment always renders a title <span> before it (see the
92	      // title and boxedHeader tests), so its absence is the DOM landmark for "not boxed."
93	      const floatingBox = closeButton.parentElement;
94	      expect(floatingBox?.children).toHaveLength(1);
95	      // CSS proof of the same thing: zimmDrawer.css.ts's closeButton part is `position: absolute`
96	      // (unconditioned by any variant/breakpoint), unlike the header part above.
97	      expect(floatingBox).toHaveStyle({ position: 'absolute' });
98	    });
99	  });
100	
101	  describe('labelledBy + boxedHeader (new path)', () => {
102	    test('close button renders boxed (in-flow header row, empty title span); the dialog is still named from the external labelledBy target', () => {
103	      renderDrawer(
104	        <div>
105	          <h2 id="ext-label-2">Another external heading</h2>
106	          <ZimmDrawer isOpen onClose={vi.fn()} size="prompt" labelledBy="ext-label-2" boxedHeader>
107	            <p>Body content</p>
108	          </ZimmDrawer>
109	        </div>,
110	      );
111	
112	      const dialog = screen.getByRole('dialog', { name: 'Another external heading' });
113	      expect(dialog).toBeInTheDocument();
114	
115	      const closeButton = screen.getByRole('button', { name: 'Close' });
116	      expect(closeButton).toBeInTheDocument();
117	
118	      // Structural (DOM-landmark) proof of "boxed, not floating": the same header box the `title`
119	      // case renders above — an empty title <span> occupying the header's flex-1 slot, immediately
120	      // followed by a close-button row — rather than the close button alone (the previous describe
121	      // block's floatingBox). This is the mechanical signal jsdom can actually observe. One level
122	      // deeper than before the SFCC-831/689 rework — see the `title` case above for why.
123	      const headerBox = closeButton.parentElement?.parentElement;
124	      expect(headerBox?.children).toHaveLength(2);
125	      expect(headerBox?.children[0].tagName).toBe('SPAN');
126	      expect(headerBox?.children[0]).toHaveTextContent('');
127	      // No id on the empty span — only the `title` case labels via id (see index.tsx); the
128	      // dialog's accessible name must keep coming from the external labelledBy target, not this
129	      // span, confirmed above via the dialog's own accessible name.
130	      expect(headerBox?.children[0]).not.toHaveAttribute('id');
131	      // children[1] is now the close button's own wrapper row (`headerCloseButton`), not the
132	      // button element itself — it still contains the same button.
133	      expect(headerBox?.children[1]).toContainElement(closeButton);
134	
135	      // CSS proof of the same thing: no `position: absolute` override here, matching the `title`
136	      // case's header box and unlike the previous describe block's floating close button.
137	      //
138	      // What this test cannot prove: jsdom has no layout engine, so none of the above shows the
139	      // close button actually lands in the same real on-screen position `title`'s header produces,
140	      // only that the same recipe part (and therefore the same declared CSS, including the
141	      // non-absolute position) is applied. Genuine visual placement still needs a real browser —
142	      // Storybook or a manual check — not this test.
143	      expect(headerBox).not.toHaveStyle({ position: 'absolute' });
144	    });
145	  });
146	});
147	
148	// SFCC-831/689 rework (Finding 4b, UNIFORM U1) — `CLOSE_LABEL_FALLBACK` (this component's own
149	// fallback constant) and the `drawer.close` entry in seedDrawerCloseUiCopy.mjs's `ENTRIES` used to
150	// be two independently hand-typed copies of the string 'Close', with nothing enforcing they
