#!/usr/bin/env node
// Read-only verification. Queries only (client.entry.getMany) — never creates, publishes,
// updates, or deletes. Checks whether seedLoginDrawerUiCopy.mjs's 8 entries (SFCC-742, a
// different, already-shipped story) are actually live before that script is deleted.

import { createClient, checkEnv } from '/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/scripts/contentful/setup/_shared.mjs';

checkEnv(['CONTENTFUL_MANAGEMENT_TOKEN', 'CONTENTFUL_SPACE_ID']);
const target = 'dev';

const EXPECTED = {
  'login.drawer.email': 'Email',
  'login.drawer.sendCode': 'Send code',
  'login.drawer.signInWithApple': 'Sign in with Apple',
  'login.drawer.signInWithGoogle': 'Sign in with Google',
  'login.drawer.createAccount.heading': 'New to Zimmermann?',
  'login.drawer.createAccount.body': 'Join for exclusive offers, early access and a more personal experience.',
  'login.drawer.createAccount.cta': 'Create an account',
  'login.drawer.wishlist.description': 'You must log in or create an account to add items to your wishlist.',
};

const client = createClient();

const existing = [];
let skip = 0;
let total = Infinity;
while (existing.length < total) {
  const page = await client.entry.getMany({
    environmentId: target,
    query: { content_type: 'uiCopy', limit: 1000, skip },
  });
  total = page.total;
  existing.push(...page.items);
  skip += page.items.length;
  if (page.items.length === 0) break;
